local AppliedGUIDs = {}   -- 会话内防重复 roll（重启后清空，已附魔物品持久化）

-- 判定是否为「真实玩家」：用账号 id 区间排除 bot（本构建 GetAccountName 对 bot 返空串）
local function IsRealPlayer(player)
    if not player then return false end
    local okId, aid = pcall(player.GetAccountId, player)
    if okId and aid then
        if aid >= BOT_ID_MIN and aid <= BOT_ID_MAX then
            if CFG.DEBUG then print("[random_enchant][DBG] 排除 bot 账号 id=" .. tostring(aid)) end
            return false
        end
        return true   -- 区间外 = 真实玩家
    end
    -- 兜底：尝试账号名前缀（部分构建 GetAccountName 可用）
    local okN, acc = pcall(player.GetAccountName, player)
    if okN and acc and acc ~= "" then
        for _, p in ipairs({ "RNDBOT", "bot", "playerbot", "altbot", "roster" }) do
            if acc:sub(1, #p) == p then return false end
        end
        return true
    end
    -- 都没取到：默认放行，保证真实玩家功能可用（bot 误判代价 < 功能静默失效）
    return true
end

local function RandEnchant(item)
    if not item then return end
    local okE, entry = pcall(item.GetEntry, item)
    -- 主守卫：slot0 已有附魔则跳过（防止重复 roll）
    local okG, cur = pcall(item.GetEnchantment, item, CFG.PERM_SLOT)
    if okG and cur and cur ~= 0 then return end
    local okC, cls = pcall(item.GetClass, item)
    if not (okC and CFG.ALLOW_CLASS[cls]) then return end
    -- 槽位设计驱动分组：武器(2)出触发池，护甲(4)出被动池
    local pool = (cls == 2) and WEAPON_POOL or ARMOR_POOL
    local okQ, q = pcall(item.GetQuality, item)
    if not (okQ and q and q >= CFG.MIN_QUALITY) then return end
    -- 二次防重（best-effort）
    local okId, guid = pcall(item.GetGUIDLow, item)
    local key = (okId and guid) and guid or nil
    if key and AppliedGUIDs[key] then return end

    local pick = pool[math.random(#pool)]
    local okS, okVal = pcall(item.SetEnchantment, item, pick, CFG.PERM_SLOT)
    if okS and okVal and key then
        AppliedGUIDs[key] = true
        -- 立即落库：防止服务器重启踢人时未走保存流程导致附魔丢失（问题④）
        pcall(item.SaveToDB, item, true)
        if CFG.DEBUG then
            print("[random_enchant] 已附加 entry=" .. tostring(entry) .. " ench=" .. tostring(pick)
                  .. " pool=" .. (cls == 2 and "WEAPON" or "ARMOR"))
        end
    elseif CFG.DEBUG then
        print("[random_enchant][WARN] SetEnchantment 失败 entry=" .. tostring(entry) .. " ench=" .. tostring(pick))
    end
end

local function OnEquip(event, player, item, bag, slot)  -- PLAYER_EVENT_ON_EQUIP = 29
    if not player or not IsRealPlayer(player) then
        if CFG.DEBUG then print("[random_enchant][DBG] OnEquip skip: player=nil or not real") end
        return
    end
    RandEnchant(item)
end

-- 登录回填：扫描身上(装备栏 0..18) + 背包/包袋(bag 0..4)，对所有绿+武器/护甲补附魔。
-- 已附魔的会被 RandEnchant 守卫跳过，不重复 roll；本回合幂等。用户不满"须装备才显绿字"，此为其解。
local function Backfill(event, player)
    if not player or not IsRealPlayer(player) then return end
    for slot = 0, 18 do
        local ok, item = pcall(player.GetEquippedItemBySlot, player, slot)
        if ok and item then RandEnchant(item) end
    end
    for bag = 0, 4 do
        for slot = 0, 39 do
            local ok, item = pcall(player.GetItemByPos, player, bag, slot)
            if ok and item then RandEnchant(item) end
        end
    end
end

local function OnLootItem(event, player, item, count)    -- PLAYER_EVENT_ON_LOOT_ITEM
    if player and IsRealPlayer(player) and item then RandEnchant(item) end
end
local function OnReceiveItem(event, player, item, count) -- PLAYER_EVENT_ON_RECEIVE_ITEM
    if player and IsRealPlayer(player) and item then RandEnchant(item) end
end

RegisterPlayerEvent(3,  Backfill)        -- PLAYER_EVENT_ON_LOGIN：登录即对背包/身上物品补附魔（核心修复，event 3 已实证为本 fork 登录事件）
pcall(RegisterPlayerEvent, 32, OnLootItem)     -- PLAYER_EVENT_ON_LOOT_ITEM：拾取即附魔（本 fork 实际事件号=32，非标准 Eluna 19；pcall 安全网，挂不上则由登录/装备兜底）
pcall(RegisterPlayerEvent, 36, OnReceiveItem)  -- PLAYER_EVENT_ON_RECEIVE_ITEM：邮寄/交易/购买即附魔（标准 Eluna=36；pcall 安全网）
RegisterPlayerEvent(29, OnEquip)       -- PLAYER_EVENT_ON_EQUIP：装备兜底（保留，event 29 已实证正常）

if CFG.DEBUG then
    print("[random_enchant] 已加载：WEAPON_POOL " .. #WEAPON_POOL .. " 条 / ARMOR_POOL " .. #ARMOR_POOL .. " 条，槽位分组 + 立即落库")
end
